finicion": "CREATE UNIQUE INDEX uq_esart_usuario_documento ON esart_ref.usuarios USING btree (documento_identidad) WHERE (documento_identidad IS NOT NULL)"}, {"esquema": "esart_ref", "tabla": "usuarios", "nombre": "uq_esart_usuario_nombre_ci", "unico": true, "primario": false, "valido": true, "definicion": "CREATE UNIQUE INDEX uq_esart_usuario_nombre_ci ON esart_ref.usuarios USING btree (lower((usuario)::text)) WHERE (usuario IS NOT NULL)"}, {"esquema": "esart_ref", "tabla": "usuarios", "nombre": "usuarios_pkey", "unico": true, "primario": true, "valido": true, "definicion": "CREATE UNIQUE INDEX usuarios_pkey ON esart_ref.usuarios USING btree (id)"}], "triggers": [], "vistas": [{"esquema": "esart", "nombre": "v_permisos_efectivos", "definicion": " WITH por_rol AS (\n         SELECT ur.usuario_id,\n            rp.componente_id,\n            bool_or(rp.puede_acceder) AS puede_acceder,\n            bool_or(rp.puede_crear) AS puede_crear,\n            bool_or(rp.puede_leer) AS puede_leer,\n            bool_or(rp.puede_actualizar) AS puede_actualizar,\n            bool_or(rp.puede_eliminar) AS puede_eliminar\n           FROM ((esart.usuario_roles ur\n             JOIN esart.roles r ON (((r.id = ur.rol_id) AND r.activo)))\n             JOIN esart.rol_permisos rp ON ((rp.rol_id = r.id)))\n          GROUP BY ur.usuario_id, rp.componente_id\n        )\n SELECT u.id AS usuario_id,\n    c.id AS componente_id,\n    c.codigo AS componente,\n    COALESCE(up.puede_acceder, pr.puede_acceder, false) AS puede_acceder,\n    COALESCE(up.puede_crear, pr.puede_crear, false) AS puede_crear,\n    COALESCE(up.puede_leer, pr.puede_leer, false) AS puede_leer,\n    COALESCE(up.puede_actualizar, pr.puede_actualizar, false) AS puede_actualizar,\n    COALESCE(up.puede_eliminar, pr.puede_eliminar, false) AS puede_eliminar\n   FROM (((esart_ref.usuarios u\n     CROSS JOIN esart.componentes c)\n     LEFT JOIN por_rol pr ON (((pr.usuario_id = u.id) AND (pr.componente_id = c.id))))\n     LEFT JOIN esart.usuario_permisos up ON (((up.usuario_id = u.id) AND (up.componente_id = c.id))))\n  WHERE (u.activo AND c.activo);"}]}, "nuevas": [["esart", "tipos_unidad"], ["esart", "permisos"], ["esart", "roles_permisos"], ["esart", "intentos_inicio_sesion"], ["esart", "sesiones_usuario"], ["esart", "importaciones_excel"], ["esart", "auditoria_eventos"], ["esart", "tipos_certificacion"], ["esart", "requisitos_habilitacion"]], "columnas": [["esart_ref", "unidades_militares", "codigo", "VARCHAR(20)"], ["esart_ref", "unidades_militares", "nombre", "VARCHAR(200)"], ["esart_ref", "unidades_militares", "sigla", "VARCHAR(30)"], ["esart_ref", "unidades_militares", "unidad_superior_id", "BIGINT"], ["esart_ref", "unidades_militares", "activa", "BOOLEAN"], ["esart_ref", "unidades_militares", "fecha_creacion", "TIMESTAMP WITH TIME ZONE"], ["esart_ref", "unidades_militares", "fecha_actualizacion", "TIMESTAMP WITH TIME ZONE"], ["esart_ref", "unidades_militares", "tipo_unidad_id", "UUID"], ["esart_ref", "unidades_militares", "uuid_publico", "UUID"], ["esart", "personal_militar", "primer_nombre", "VARCHAR(60)"], ["esart", "personal_militar", "segundo_nombre", "VARCHAR(60)"], ["esart", "personal_militar", "primer_apellido", "VARCHAR(60)"], ["esart", "personal_militar", "segundo_apellido", "VARCHAR(60)"], ["esart", "personal_militar", "arma", "VARCHAR(40)"], ["esart", "personal_militar", "estado_servicio", "VARCHAR(20)"], ["esart", "hoja_vida_artillero", "especialidad", "VARCHAR(100)"], ["esart", "hoja_vida_artillero", "fecha_ingreso_arma", "DATE"], ["esart", "roles", "fecha_actualizacion", "TIMESTAMP WITH TIME ZONE"], ["esart_ref", "usuarios", "nombre_completo", "VARCHAR(200)"], ["esart_ref", "usuarios", "rol_id", "BIGINT"], ["esart_ref", "usuarios", "intentos_fallidos_consecutivos", "INTEGER"], ["esart_ref", "usuarios", "bloqueado_hasta", "TIMESTAMP WITH TIME ZONE"], ["esart", "tipos_curso", "descripcion", "TEXT"], ["esart", "tipos_curso", "tipo_sistema", "VARCHAR(50)"], ["esart", "tipos_cur